/*
 * Resources admin: the "Config (.json)" tab. Shows the resource's config (generated by the server from
 * Firestore, in the upload format) in CodeMirror; validates it on the server ~500 ms after typing stops;
 * Save shows a field-by-field diff (EN and ES side by side) and asks for confirmation; History lists the
 * last 20 saves with View diff and Restore. Every check happens on the server (one validator for the
 * upload, a .json-only upload and this tab). All text is shown with textContent, never as HTML.
 * Loaded before admin.js; admin.js hands it a dropped .json (window.JDTConfigEditor.loadFile).
 */
(function () {
  "use strict";
  var dataEl = document.getElementById("doc-data"), panel = document.getElementById("json-panel");
  if (!dataEl || !panel) return;
  var data = JSON.parse(dataEl.textContent), docId = data.doc.id, everPublished = !!data.doc.publishedAt;
  var tokenEl = document.querySelector('meta[name="csrf-token"]'), token = tokenEl ? tokenEl.content : "";
  var $ = function (id) { return document.getElementById(id); };
  var ed = null, loadedText = null, baseRev = null, status = data.doc.status, source = "json", restoredFrom = null;
  var timer = null, seq = 0, last = null;

  function api(method, url, body) {
    var opts = { method: method, credentials: "same-origin", headers: { "X-JDT-Admin": "1", "X-CSRF-Token": token } };
    if (body !== undefined) { opts.body = JSON.stringify(body); opts.headers["Content-Type"] = "application/json"; }
    return fetch(url, opts).then(function (r) {
      return r.json().catch(function () { return { ok: false, error: "HTTP " + r.status + " (not JSON; is your sign-in expired? Reload the page)." }; })
        .then(function (j) { if (!r.ok || !j.ok) { var e = new Error(j.error || "HTTP " + r.status); e.data = j; e.status = r.status; throw e; } return j; });
    });
  }
  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; }
  function say(text, kind) { var s = $("json-status"); s.textContent = text || ""; s.className = "json-status" + (kind ? " " + kind : ""); }
  function remember(k, v) { try { if (v === null) sessionStorage.removeItem(k); else sessionStorage.setItem(k, v); } catch (e) { /* private mode: fine */ } }
  function recall(k) { try { return sessionStorage.getItem(k); } catch (e) { return null; } }

  var isDirty = function () { return !!ed && loadedText !== null && ed.getText() !== loadedText; };
  window.addEventListener("beforeunload", function (e) { if (isDirty()) { e.preventDefault(); e.returnValue = ""; } });

  // ---- editor and live validation ------------------------------------------------------------
  function ensureEditor() {
    if (ed) return;
    if (!window.JDTCodeMirror) { say("The code editor didn't load. Reload the page.", "err"); return; }
    ed = window.JDTCodeMirror.create($("json-editor"), "", function () {
      note = "";
      $("json-save").disabled = true;
      say("Checking…");
      clearTimeout(timer);
      timer = setTimeout(check, 500);
    });
  }
  // `note` (what just happened) stays in front of the validation summary until the next edit
  var note = "";
  function setText(text, why) {
    ensureEditor();
    ed.setText(text);
    clearTimeout(timer); // the change listener's check: this one replaces it
    note = why || "";
    return check();
  }
  function load(message) {
    ensureEditor();
    say("Loading…");
    return api("GET", "/api/resources/" + docId + "/config.json").then(function (j) {
      loadedText = j.text; baseRev = j.rev; status = j.status; source = "json"; restoredFrom = null;
      ed.setText(j.text);
      clearTimeout(timer);
      note = message || "";
      return check().then(function () { loadHistory(); });
    }, function (e) { say(e.message, "err"); });
  }
  function check() {
    if (!ed) return Promise.resolve();
    var my = ++seq;
    return api("POST", "/api/resources/" + docId + "/config/check", { text: ed.getText() }).then(function (j) {
      if (my !== seq) return j;
      last = j;
      showProblems(j.errors, j.warnings);
      var changed = isDirty();
      $("json-save").disabled = !j.valid || !changed;
      var pre = note ? note + " " : "";
      if (!j.valid) say(pre + j.errors.length + (j.errors.length === 1 ? " error" : " errors") + (j.warnings.length ? " and " + j.warnings.length + " warning(s)" : "") + ". Save is off until the errors are fixed.", "err");
      else if (j.warnings.length) say(pre + "Valid, with " + j.warnings.length + " warning(s)." + (changed ? "" : " No changes yet."), "warn");
      else say(pre + (changed ? "Valid." : "Valid. No changes yet."), "ok");
      return j;
    }, function (e) { if (my === seq) say(e.message, "err"); });
  }
  function showProblems(errors, warnings) {
    var ul = $("json-problems");
    ul.textContent = "";
    [["err", errors || []], ["warn", warnings || []]].forEach(function (g) {
      g[1].forEach(function (p) {
        var li = el("li", "jp jp-" + g[0]);
        var b = el("button", "jp-btn");
        b.type = "button";
        b.appendChild(el("span", "jp-kind", g[0] === "err" ? "Error" : "Warning"));
        b.appendChild(el("span", "jp-line", p.line ? "line " + p.line : ""));
        b.appendChild(el("span", "jp-msg", p.message));
        b.addEventListener("click", function () { if (ed && p.line) ed.gotoLine(p.line); });
        li.appendChild(b);
        ul.appendChild(li);
      });
    });
  }

  // ---- the diff ----------------------------------------------------------------------------
  function side(s) {
    var box = el("div", "jd-side");
    if (!s) { box.appendChild(el("span", "jd-same", "unchanged")); return box; }
    (s.segments.length ? s.segments : [{ op: "=", text: "" }]).forEach(function (g) {
      box.appendChild(el(g.op === "+" ? "ins" : g.op === "-" ? "del" : "span", "", g.text));
    });
    return box;
  }
  function renderDiff(d, box) {
    box.textContent = "";
    if (!d || !d.changed) { box.appendChild(el("p", "jd-none", "No differences.")); return; }
    if (d.shared.length) {
      var t = el("table", "jd-table");
      var hr = el("tr"); ["Field", "Before", "After"].forEach(function (h) { hr.appendChild(el("th", "", h)); }); t.appendChild(hr);
      d.shared.forEach(function (r) {
        var tr = el("tr");
        tr.appendChild(el("th", "", r.label));
        tr.appendChild(el("td", "jd-before", r.before || "(none)"));
        tr.appendChild(el("td", "jd-after", r.after || "(none)"));
        t.appendChild(tr);
      });
      box.appendChild(t);
    }
    if (d.text.length) {
      var g = el("div", "jd-grid");
      ["", "English", "Español"].forEach(function (h) { g.appendChild(el("div", "jd-head", h)); });
      d.text.forEach(function (r) {
        g.appendChild(el("div", "jd-label", r.label));
        g.appendChild(side(r.en));
        g.appendChild(side(r.es));
      });
      box.appendChild(g);
    }
  }
  function slugNotes(d) {
    return (d && d.slugChanges || []).map(function (c) {
      var base = c.lang === "es" ? "/es/recursos/" : "/resources/";
      return "The " + c.lang.toUpperCase() + " URL changes from " + base + c.from + "/ to " + base + c.to + "/. " +
        (everPublished ? "The old URL will 301 to the new one; tell Search Console (URL Inspection → Request indexing for the new URL)."
          : "It was never published, so there's nothing to redirect.");
    });
  }

  // ---- the dialog ----------------------------------------------------------------------------
  var dialog = $("json-dialog"), okBtn = $("json-dialog-ok"), dlgCheck = $("json-dialog-check"), onOk = null;
  function openDialog(opts) {
    $("json-dialog-h").textContent = opts.title;
    var note = $("json-dialog-note");
    note.textContent = "";
    (opts.notes || []).forEach(function (n) { note.appendChild(el("span", "jd-note", n)); });
    note.hidden = !(opts.notes || []).length;
    renderDiff(opts.diff, $("json-diff"));
    $("json-dialog-check-row").hidden = !opts.needCheck;
    dlgCheck.checked = false;
    okBtn.hidden = !opts.ok;
    okBtn.textContent = opts.ok || "";
    okBtn.disabled = !!opts.needCheck;
    onOk = opts.onOk || null;
    if (dialog.showModal) dialog.showModal(); else dialog.setAttribute("open", "");
  }
  dlgCheck.addEventListener("change", function () { okBtn.disabled = !dlgCheck.checked; });
  okBtn.addEventListener("click", function () { if (onOk) onOk(); });
  function closeDialog() { if (dialog.close) dialog.close(); else dialog.removeAttribute("open"); }

  // ---- save --------------------------------------------------------------------------------
  $("json-save").addEventListener("click", function () {
    var b = this; b.disabled = true;
    clearTimeout(timer);
    check().then(function (j) {
      if (!j || !j.valid) return;
      if (!j.diff || !j.diff.changed) { say("Nothing to save: this is the current config.", "ok"); return; }
      var live = status === "published";
      openDialog({
        title: (source === "upload" ? "Save the uploaded .json?" : restoredFrom !== null ? "Restore this version?" : "Save these changes?"),
        notes: slugNotes(j.diff).concat(live ? ["This resource is live: the page updates within about 30 seconds."] : [])
          .concat(j.warnings.length ? [j.warnings.length + " warning(s) are listed under the editor."] : []),
        diff: j.diff, needCheck: live, ok: live ? "Update live page" : "Save", onOk: save,
      });
    }).then(function () { b.disabled = !(last && last.valid) || !isDirty(); });
  });
  function save() {
    okBtn.disabled = true;
    var body = { text: ed.getText(), rev: baseRev, checked: dlgCheck.checked, source: source };
    if (restoredFrom !== null) body.restoredFrom = restoredFrom;
    api("PUT", "/api/resources/" + docId + "/config.json", body).then(function (j) {
      closeDialog();
      loadedText = j.text;
      if (j.unchanged) { say("Nothing changed.", "ok"); return; }
      // the form, the files list and the header show the old data: reload into this tab
      remember("jdt-json-msg", status === "published" ? "Saved. The live page updates within about 30 seconds." : "Saved.");
      location.hash = "#json";
      location.reload();
    }, function (e) {
      var d = e.data || {};
      if (d.stale) {
        openDialog({
          title: "Not saved: someone else saved first", notes: [e.message], diff: d.diff, ok: "Load the current version (discards your edits)",
          onOk: function () { closeDialog(); load("Loaded the current version."); },
        });
        return;
      }
      closeDialog();
      if (d.errors) showProblems(d.errors, d.warnings);
      if (d.problems) showProblems(d.problems.map(function (m) { return { message: m }; }), []);
      say(e.message, "err");
    });
  }

  // ---- download / upload / discard -------------------------------------------------------------
  $("json-download").addEventListener("click", function (e) {
    if (isDirty() && !confirm("Download saves the current config from the server, not your unsaved edits. Continue?")) e.preventDefault();
  });
  $("json-load").addEventListener("click", function () { $("json-file").click(); });
  $("json-file").addEventListener("change", function () { var f = this.files[0]; this.value = ""; if (f) loadFile(f); });
  function loadFile(file) {
    if (file.size > 256 * 1024) { say(file.name + " is over 256 KB.", "err"); return; }
    showTab("json", true).then(function (ok) {
      if (!ok) return;
      if (isDirty() && !confirm("Replace your unsaved edits with " + file.name + "?")) return;
      file.text().then(function (t) {
        source = "upload"; restoredFrom = null;
        setText(t.replace(/^﻿/, ""), "Loaded " + file.name + " (not saved). Check the problems, then Save to see exactly what it changes.");
      });
    });
  }
  $("json-reload").addEventListener("click", function () {
    if (isDirty() && !confirm("Discard your changes in the JSON?")) return;
    load("Reloaded from the server.");
  });

  // ---- history -----------------------------------------------------------------------------
  var SOURCE = { form: "Form", json: "JSON tab", upload: "Upload" };
  function when(iso) { return String(iso || "").slice(0, 16).replace("T", " ") + " UTC"; }
  function loadHistory() {
    var ol = $("json-history");
    api("GET", "/api/resources/" + docId + "/revisions").then(function (j) {
      ol.textContent = "";
      if (!j.revisions.length) { ol.appendChild(el("li", "hint", "No saves yet.")); return; }
      j.revisions.forEach(function (r) {
        var li = el("li", "jh");
        li.appendChild(el("span", "jh-what", "Before the " + (SOURCE[r.source] || r.source) + " save of " + when(r.savedAt) + " by " + (r.savedBy || "?") +
          (r.restoredFrom !== undefined && r.restoredFrom !== null ? " (a restore of #" + r.restoredFrom + ")" : "") + " · #" + r.n));
        var v = el("button", "btn btn-small", "View diff"); v.type = "button";
        v.addEventListener("click", function () {
          api("GET", "/api/resources/" + docId + "/revisions/" + r.n).then(function (x) {
            openDialog({ title: "#" + r.n + " → now", notes: ["What changed from this version (" + when(r.savedAt) + ") to the current one."], diff: x.diff });
          }, function (e) { say(e.message, "err"); });
        });
        var rs = el("button", "btn btn-small", "Restore"); rs.type = "button";
        rs.addEventListener("click", function () {
          if (isDirty() && !confirm("Replace your unsaved edits with version #" + r.n + "?")) return;
          api("GET", "/api/resources/" + docId + "/revisions/" + r.n).then(function (x) {
            source = "json"; restoredFrom = r.n;
            setText(x.revision.config, "Loaded #" + r.n + " into the editor (not saved). Save shows what restoring it changes.");
            ed.gotoLine(1);
          }, function (e) { say(e.message, "err"); });
        });
        li.appendChild(v); li.appendChild(rs);
        ol.appendChild(li);
      });
    }, function (e) { ol.textContent = ""; ol.appendChild(el("li", "err", e.message)); });
  }

  // ---- tabs (the form and this tab edit the same data) ------------------------------------------
  var formParts = ["files-card", "edit"], current = "form";
  function showTab(which, quiet) {
    if (which === current) return Promise.resolve(true);
    if (which === "json") {
      var formDirty = window.JDTAdmin && window.JDTAdmin.isDirty();
      if (formDirty) {
        if (!confirm("The form has unsaved changes. Discard them and open the JSON?")) return Promise.resolve(false);
        window.JDTAdmin.discard();
      }
    } else if (isDirty() && !confirm("The JSON has unsaved changes. Discard them and go back to the form?")) {
      return Promise.resolve(false);
    }
    current = which;
    var json = which === "json";
    panel.hidden = !json;
    formParts.forEach(function (id) { $(id).hidden = json; });
    $("save").hidden = json;
    $("tab-form").setAttribute("aria-selected", json ? "false" : "true");
    $("tab-json").setAttribute("aria-selected", json ? "true" : "false");
    if (history.replaceState) history.replaceState(null, "", json ? "#json" : location.pathname + location.search);
    if (json) return load(quiet ? null : recall("jdt-json-msg")).then(function () { remember("jdt-json-msg", null); return true; });
    loadedText = null; // leaving: the next visit loads fresh from the server
    $("json-save").disabled = true;
    return Promise.resolve(true);
  }
  $("tab-form").addEventListener("click", function () { showTab("form"); });
  $("tab-json").addEventListener("click", function () { showTab("json"); });
  if (location.hash === "#json") showTab("json");
  window.addEventListener("hashchange", function () { if (location.hash === "#json") showTab("json"); });

  window.JDTConfigEditor = { loadFile: loadFile, isDirty: isDirty };
})();
